-- Module-scoped progress and recordings; legacy payloads and recordings remain Show.
-- Existing Show catalogue, event IDs, run IDs, answers and blobs are not rewritten.
alter table polysemy_private.recordings add column module text not null default 'show' references polysemy_private.catalogue(module);
create index polysemy_lab_recording_module on polysemy_private.recordings(module);
create function polysemy_private.sync_modules(p_token uuid,p_events jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_student uuid; e jsonb; q jsonb; v_kind text; v_correct boolean; v_at timestamptz; v_result jsonb; v_module text;
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='28000'; end if;
 v_student:=public.flashcard_session_student_id(p_token);
 if v_student is null then raise exception 'Student session expired. Please sign in again.' using errcode='28000'; end if;
 if jsonb_typeof(p_events) is distinct from 'array' or jsonb_array_length(p_events)>100 then raise exception 'Invalid event batch' using errcode='22023'; end if;
 for e in select value from jsonb_array_elements(p_events) loop
  v_kind:=e->>'kind';v_correct:=null;v_module:=coalesce(e->>'module','show');
  if not exists(select 1 from polysemy_private.catalogue c where c.module=v_module) then raise exception 'Unknown module' using errcode='22023';end if;
  if v_kind is null or v_kind not in ('view','start','answer','time') or e->>'id' is null or e->>'at' is null then raise exception 'Invalid event' using errcode='22023'; end if;
  v_at:=(e->>'at')::timestamptz;
  if not isfinite(v_at) or v_at>now()+interval '5 minutes' or v_at<now()-interval '90 days' then raise exception 'Invalid event date' using errcode='22023'; end if;
  if v_kind='view' and not exists(select 1 from polysemy_private.catalogue c where c.module=v_module and c.senses ? (e->>'sense')) then raise exception 'Unknown meaning' using errcode='22023'; end if;
  if v_kind in ('start','answer') and e->>'run' is null then raise exception 'Missing practice run' using errcode='22023'; end if;
  if v_kind='answer' then
   select c.questions->(e->>'question') into q from polysemy_private.catalogue c where c.module=v_module;
   if q is null or coalesce((e->>'round')::integer,0) not between 1 and 1000 or not coalesce(q->'options' ? (e->>'choice'),false) then raise exception 'Invalid answer' using errcode='22023'; end if;
   if not exists(select 1 from polysemy_private.events t where t.student_id=v_student and t.module=v_module and t.kind='start' and t.run=(e->>'run')::uuid) then raise exception 'Unknown practice run' using errcode='22023'; end if;
   v_correct:=e->>'choice'=q->>'answer';
  end if;
  if v_kind='time' and coalesce((e->>'seconds')::integer,0) not between 1 and 60 then raise exception 'Invalid study duration' using errcode='22023'; end if;
  insert into polysemy_private.events(student_id,id,module,kind,run,round,question,choice,sense,correct,seconds,happened_at)
  values(v_student,(e->>'id')::uuid,v_module,v_kind,case when v_kind in ('start','answer') then (e->>'run')::uuid end,case when v_kind='answer' then (e->>'round')::integer end,case when v_kind='answer' then e->>'question' end,case when v_kind='answer' then e->>'choice' end,case when v_kind='view' then e->>'sense' end,v_correct,case when v_kind='time' then (e->>'seconds')::integer end,v_at)
  on conflict do nothing;
 end loop;
 select jsonb_build_object('events',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',t.id,'module',t.module,'kind',t.kind,'run',t.run,'round',t.round,'question',t.question,'choice',t.choice,'sense',t.sense,'at',t.happened_at)) order by t.happened_at,t.id) from polysemy_private.events t where t.student_id=v_student and t.kind<>'time'),'[]'::jsonb),
 'timeDays',coalesce((select jsonb_agg(to_jsonb(d) order by d.date) from (select (t.happened_at at time zone 'Asia/Hong_Kong')::date as date,sum(t.seconds)::bigint as seconds from polysemy_private.events t where t.student_id=v_student and t.kind='time' group by 1)d),'[]'::jsonb),'updatedAt',now()) into v_result;
 return v_result;
end;$$;

create function polysemy_private.recording_modules(p_token uuid,p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare sid uuid; data bytea; result jsonb; mt text; v_module text;
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='28000';end if;
 sid:=public.flashcard_session_student_id(p_token);
 if sid is null then raise exception 'Student session expired' using errcode='28000';end if;
 if p_action='list' then
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'question',r.question,'module',r.module,'mime',r.mime,'at',r.at) order by r.at desc),'[]'::jsonb) into result from polysemy_private.recordings r where r.student_id=sid;return result;
 elsif p_action='get' then
 select jsonb_build_object('mime',r.mime,'audio',replace(encode(r.audio,'base64'),E'\n','')) into result from polysemy_private.recordings r where r.student_id=sid and r.id=(p_payload->>'id')::uuid;
 if result is null then raise exception 'Recording not found' using errcode='22023';end if;return result;
 elsif p_action='save' then
 v_module:=coalesce(p_payload->>'module','show');
 if coalesce(length(p_payload->>'audio'),0) not between 40 and 2796204 or coalesce(p_payload->>'mime','') not in ('audio/webm','audio/mp4','audio/ogg','audio/mpeg','audio/wav') or p_payload->>'id' is null then raise exception 'Invalid recording' using errcode='22023';end if;
 if not exists(select 1 from polysemy_private.catalogue c where c.module=v_module and c.questions ? (p_payload->>'question')) then raise exception 'Unknown question' using errcode='22023';end if;
 data:=decode(p_payload->>'audio','base64');mt:=p_payload->>'mime';
 if octet_length(data) not between 32 and 2097152 or not ((mt='audio/webm' and substring(data from 1 for 4)=decode('1a45dfa3','hex')) or (mt='audio/mp4' and substring(data from 5 for 4)=convert_to('ftyp','UTF8')) or (mt='audio/ogg' and substring(data from 1 for 4)=convert_to('OggS','UTF8')) or (mt='audio/mpeg' and (substring(data from 1 for 3)=convert_to('ID3','UTF8') or (get_byte(data,0)=255 and (get_byte(data,1)&224)=224))) or (mt='audio/wav' and substring(data from 1 for 4)=convert_to('RIFF','UTF8') and substring(data from 9 for 4)=convert_to('WAVE','UTF8'))) then raise exception 'Invalid audio container' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(sid::text,65));
 if not exists(select 1 from polysemy_private.recordings r where r.student_id=sid and r.id=(p_payload->>'id')::uuid) and (select coalesce(sum(octet_length(audio)),0) from polysemy_private.recordings where student_id=sid)+octet_length(data)>104857600 then raise exception 'Recording storage full' using errcode='22023';end if;
 insert into polysemy_private.recordings(student_id,id,module,question,mime,audio) values(sid,(p_payload->>'id')::uuid,v_module,p_payload->>'question',mt,data) on conflict do nothing;return jsonb_build_object('saved',true);
 end if;
 raise exception 'Unknown action' using errcode='22023';
end;$$;

notify pgrst,'reload schema';

