-- New endpoints isolate older open Show-only browser tabs from multi-module data.
revoke all on function polysemy_private.sync_modules(uuid,jsonb) from public,anon,authenticated;
grant execute on function polysemy_private.sync_modules(uuid,jsonb) to authenticated;
create function public.polysemy_lab_modules_sync(p_token uuid,p_events jsonb default '[]'::jsonb) returns jsonb
language sql security invoker set search_path='' as $$select polysemy_private.sync_modules(p_token,p_events);$$;
revoke all on function public.polysemy_lab_modules_sync(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.polysemy_lab_modules_sync(uuid,jsonb) to authenticated;
revoke all on function polysemy_private.recording_modules(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function polysemy_private.recording_modules(uuid,text,jsonb) to authenticated;
create function public.polysemy_lab_modules_recording(p_token uuid,p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb
language sql security invoker set search_path='' as $$select polysemy_private.recording_modules(p_token,p_action,p_payload);$$;
revoke all on function public.polysemy_lab_modules_recording(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.polysemy_lab_modules_recording(uuid,text,jsonb) to authenticated;

create or replace function polysemy_private.recording(p_token uuid,p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare sid uuid; data bytea; result jsonb; mt text;
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='28000';end if;
 sid:=public.flashcard_session_student_id(p_token);
 if sid is null then raise exception 'Student session expired' using errcode='28000';end if;
 if p_action='list' then
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'question',r.question,'mime',r.mime,'at',r.at) order by r.at desc),'[]'::jsonb) into result from polysemy_private.recordings r where r.module='show' and r.student_id=sid;return result;
 elsif p_action='get' then
 select jsonb_build_object('mime',r.mime,'audio',replace(encode(r.audio,'base64'),E'\n','')) into result from polysemy_private.recordings r where r.module='show' and r.student_id=sid and r.id=(p_payload->>'id')::uuid;
 if result is null then raise exception 'Recording not found' using errcode='22023';end if;return result;
 elsif p_action='save' then
 if coalesce(length(p_payload->>'audio'),0) not between 40 and 2796204 or coalesce(p_payload->>'mime','') not in ('audio/webm','audio/mp4','audio/ogg','audio/mpeg','audio/wav') or p_payload->>'id' is null then raise exception 'Invalid recording' using errcode='22023';end if;
 if not exists(select 1 from polysemy_private.catalogue c where c.module='show' and c.questions ? (p_payload->>'question')) then raise exception 'Unknown question' using errcode='22023';end if;
 data:=decode(p_payload->>'audio','base64');mt:=p_payload->>'mime';
 if octet_length(data) not between 32 and 2097152 or not ((mt='audio/webm' and substring(data from 1 for 4)=decode('1a45dfa3','hex')) or (mt='audio/mp4' and substring(data from 5 for 4)=convert_to('ftyp','UTF8')) or (mt='audio/ogg' and substring(data from 1 for 4)=convert_to('OggS','UTF8')) or (mt='audio/mpeg' and (substring(data from 1 for 3)=convert_to('ID3','UTF8') or (get_byte(data,0)=255 and (get_byte(data,1)&224)=224))) or (mt='audio/wav' and substring(data from 1 for 4)=convert_to('RIFF','UTF8') and substring(data from 9 for 4)=convert_to('WAVE','UTF8'))) then raise exception 'Invalid audio container' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(sid::text,65));
 if not exists(select 1 from polysemy_private.recordings r where r.module='show' and r.student_id=sid and r.id=(p_payload->>'id')::uuid) and (select coalesce(sum(octet_length(audio)),0) from polysemy_private.recordings where student_id=sid)+octet_length(data)>104857600 then raise exception 'Recording storage full' using errcode='22023';end if;
 insert into polysemy_private.recordings(student_id,id,question,mime,audio) values(sid,(p_payload->>'id')::uuid,p_payload->>'question',mt,data) on conflict do nothing;return jsonb_build_object('saved',true);
 end if;
 raise exception 'Unknown action' using errcode='22023';
end;$$;

